<script setup lang="ts">
import DownloadLink from "../../Components/DownloadLink.vue";
import Pagination from "../../Components/Pagination.vue";import{Link}from'@inertiajs/vue3';import MainLayout from'../../Layouts/MainLayout.vue';import{reactive}from'vue';const p=defineProps<{items:any;filters:any;summary:any}>(),f=reactive({...p.filters});const qs=()=>new URLSearchParams(Object.entries(f).filter(([,v])=>v).map(([k,v])=>[k,String(v)])).toString();const rp=(v:any)=>Number(v??0).toLocaleString('id-ID');</script>
<template><MainLayout><main class="p-4 sm:p-6 lg:p-8"><div class="mx-auto max-w-7xl"><div class="mb-6 flex flex-wrap items-end justify-between gap-3"><div><p class="text-sm font-bold uppercase tracking-widest text-indigo-600">Analitik</p><h1 class="mt-2 text-2xl font-bold">Laporan transaksi</h1><p class="text-sm text-slate-500">Ringkasan dan histori transaksi tabungan siswa.</p></div><div class="flex gap-2"><DownloadLink :href="`/laporan/export-xlsx?${qs()}`" class="rounded-lg border px-4 py-2.5 text-sm font-semibold">↓ Excel (.xlsx)</DownloadLink><DownloadLink :href="`/laporan/export-pdf?${qs()}`" class="sneat-primary rounded-lg px-4 py-2.5 text-sm font-semibold text-white">↓ PDF</DownloadLink></div></div><section class="sneat-card mb-6 p-5"><div class="grid gap-4 sm:grid-cols-4 sm:items-end"><input aria-label="Tanggal mulai" v-model="f.start_date" type="date"><input aria-label="Tanggal akhir" v-model="f.end_date" type="date"><select aria-label="Jenis transaksi" v-model="f.jenis"><option value="">Semua jenis</option><option value="masuk">Setoran</option><option value="keluar">Penarikan</option></select><Link :href="`/laporan?${qs()}`" class="sneat-primary rounded-lg px-4 py-2.5 text-center text-sm font-semibold text-white">Terapkan filter</Link><Link href="/laporan" class="text-sm text-indigo-600">Reset filter</Link></div></section><div class="mb-6 grid gap-4 sm:grid-cols-3"><div class="sneat-card p-5">Total transaksi<strong class="mt-2 block text-2xl">{{p.summary.count}}</strong></div><div class="rounded-lg bg-emerald-50 p-5 text-emerald-700">Total setoran<strong class="mt-2 block text-xl">Rp {{rp(p.summary.masuk)}}</strong></div><div class="rounded-lg bg-rose-50 p-5 text-rose-700">Total penarikan<strong class="mt-2 block text-xl">Rp {{rp(p.summary.keluar)}}</strong></div></div><section class="sneat-card overflow-hidden"><div class="border-b p-5"><b>Detail transaksi</b></div><div class="overflow-x-auto"><table class="sneat-table w-full text-left text-sm"><thead class="text-xs uppercase"><tr><th class="p-4">Tanggal</th><th class="p-4">Siswa</th><th class="p-4">Jenis</th><th class="p-4 text-right">Jumlah</th><th class="p-4 text-right">Saldo</th><th class="p-4">Keterangan</th></tr></thead><tbody class="divide-y"><tr v-for="x in p.items.data" :key="x.id"><td class="p-4">{{x.tanggal}}</td><td class="p-4 font-semibold">{{x.siswa}}</td><td class="p-4">{{x.jenis==='masuk'?'Setoran':'Penarikan'}}</td><td class="p-4 text-right">Rp {{rp(x.jumlah)}}</td><td class="p-4 text-right">Rp {{rp(x.saldo)}}</td><td class="p-4 text-slate-500">{{x.keterangan||'—'}}</td></tr><tr v-if="!p.items.data.length"><td colspan="6" class="p-8 text-center text-slate-500">Tidak ada transaksi untuk filter ini.</td></tr></tbody></table></div><Pagination :data="p.items" /></section></div></main></MainLayout></template>
